using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
using System.Text;
using System.Web.Script.Serialization;
class TestAppLibrary {
 static int checks;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;}
 static void Reject(Action operation,string name){bool rejected=false;try{operation();}catch{rejected=true;}Check(rejected,name);}
 static void Shortcut(string path,string target,string arguments){
  // WScript's ANSI shortcut writer cannot create this Unicode fixture on an English runner.
  object raw=new ShellLink();try{var link=(IShellLinkW)raw;link.SetPath(target);link.SetArguments(arguments);((IPersistFile)raw).Save(path,true);}finally{Marshal.FinalReleaseComObject(raw);}
 }
 [ComImport,Guid("00021401-0000-0000-C000-000000000046")]class ShellLink{}
 [ComImport,Guid("000214F9-0000-0000-C000-000000000046"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface IShellLinkW{
  void GetPath([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder path,int count,IntPtr data,uint flags);
  void GetIDList(out IntPtr value);void SetIDList(IntPtr value);
  void GetDescription([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder value,int count);void SetDescription([MarshalAs(UnmanagedType.LPWStr)]string value);
  void GetWorkingDirectory([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder value,int count);void SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)]string value);
  void GetArguments([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder value,int count);void SetArguments([MarshalAs(UnmanagedType.LPWStr)]string value);
  void GetHotkey(out short value);void SetHotkey(short value);void GetShowCmd(out int value);void SetShowCmd(int value);
  void GetIconLocation([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder value,int count,out int index);void SetIconLocation([MarshalAs(UnmanagedType.LPWStr)]string value,int index);
  void SetRelativePath([MarshalAs(UnmanagedType.LPWStr)]string value,uint reserved);void Resolve(IntPtr hwnd,uint flags);void SetPath([MarshalAs(UnmanagedType.LPWStr)]string value);
 }
 static AppLibraryEntry Found(string path,string target,string args){return new AppLibraryEntry{identity=AppLibrary.Identity(target,args),path=path,target=target,arguments="",name="Fixture",kind="app",exists=true,sources=new List<string>{path}};}
 static void DedupChecks(string fixture){
  string[][] sources={new[]{"quark.exe","--launch-from=desktopicon --brand-quark","--launch-from=startmenu --brand-quark"},new[]{"quark_cloud_drive.exe","--launch-from=desktopicon --brand-clouddrive","--launch-from=startmenu --brand-clouddrive"},new[]{"JianyingPro.exe","--src1","--src3"},new[]{"LeFile.exe","-origin=desktop","-origin=startmenu"},new[]{"SLBrowser.exe","--from=desktopshortcut","--from=startmenu"},new[]{"LZMain.exe","--from=desktop","--from=startmenu"},new[]{"LenovoAppStoreNotify.exe","-c shortcut_desktop","-c shortcut_startmenu"},new[]{"ThunderStart.exe","-StartType:DesktopIcon","-StartType:StartMenu"},new[]{"chrome.exe","--source-shortcut-location=desktop","--source-shortcut-location=start-menu"},new[]{"MarvisLauncher.exe","--from \"2\" --launch-proc-name \"Marvis.exe\"","--from \"4\" --launch-proc-name \"Marvis.exe\""},new[]{"ksolaunch.exe","/prometheus /fromksolaunch /from=desktop_shortcut","/prometheus /fromksolaunch /from=startmenu"}};
  foreach(var row in sources){string target=Path.Combine(fixture,row[0]);Check(AppLibrary.MatchIdentity(AppLibrary.Identity(target,row[1]))==AppLibrary.MatchIdentity(AppLibrary.Identity(target,row[2])),row[0]+" launch-source aliases merge");Check(AppLibrary.MatchIdentity(AppLibrary.Identity(target,row[1]+" --profile A"))!=AppLibrary.MatchIdentity(AppLibrary.Identity(target,row[2]+" --profile B")),row[0]+" different profiles stay separate");}
  Check(AppLibrary.MatchIdentity(AppLibrary.Identity(Path.Combine(fixture,"unknown.exe"),"--src1"))!=AppLibrary.MatchIdentity(AppLibrary.Identity(Path.Combine(fixture,"unknown.exe"),"--src3")),"source-like flags on unknown apps are significant");
  Check(AppLibrary.MatchIdentity(AppLibrary.Identity(Path.Combine(fixture,"pwsh.exe"),"-File \"工作.ps1\""))!=AppLibrary.MatchIdentity(AppLibrary.Identity(Path.Combine(fixture,"pwsh.exe"),"-File \"娱乐.ps1\"")),"script targets remain distinct");
  string targetPath=Path.Combine(fixture,"quark.exe"),desktop=Path.Combine(fixture,"desktop.lnk"),menu=Path.Combine(fixture,"menu.lnk");File.WriteAllText(targetPath,"");Shortcut(desktop,targetPath,sources[0][1]);Shortcut(menu,targetPath,sources[0][2]);
  var a=Found(desktop,targetPath,sources[0][1]);a.id="keep-id";a.manual=true;a.category="work";a.folder="chosen-folder";a.order=23;a.alias="我的浏览器";
  var b=Found(menu,targetPath,sources[0][2]);b.id="duplicate-id";var state=new AppLibrarySnapshot();state.entries.Add(a);state.entries.Add(b);AppLibrary.Merge(state,new[]{Found(desktop,targetPath,sources[0][1]),Found(menu,targetPath,sources[0][2])});
  Check(state.entries.Count==1&&state.entries[0]==a&&a.path==desktop&&a.target==targetPath&&a.arguments=="","legacy aliases merge without changing the retained ID or launch signature");
  Check(a.category=="work"&&a.folder=="chosen-folder"&&a.order==23&&a.alias=="我的浏览器"&&a.sources.Count==2,"dedup retains manual placement, alias and both sources");
  state.excluded.Add(a.identity);state.entries.Clear();AppLibrary.Merge(state,new[]{Found(desktop,targetPath,sources[0][1]),Found(menu,targetPath,sources[0][2])});Check(state.entries.Count==0,"removing one canonical app excludes all launch-source aliases");
  using(var library=new AppLibrary(Path.Combine(fixture,"dedup"))){library.Add(desktop);string id=library.GetSnapshot().entries.Single(e=>e.kind!="action").id;library.Add(menu);Check(library.GetSnapshot().entries.Count(e=>e.kind!="action")==1&&library.Find(id)!=null,"manual alias addition keeps existing ID");library.Apply("remove",id,"","");library.Add(menu);Check(library.GetSnapshot().entries.Count(e=>e.kind!="action")==1,"explicit add clears equivalent legacy exclusions");}
  string oldTarget=Path.Combine(fixture,"old-version.exe"),newTarget=Path.Combine(fixture,"new-version.exe");File.WriteAllText(newTarget,"");var old=Found(desktop,oldTarget,"");old.id="upgrade-id";old.exists=false;old.category="work";old.folder="chosen-folder";old.order=4;var newer=Found(desktop,newTarget,"");newer.id="recent-duplicate";newer.category="uncategorized";
  state=new AppLibrarySnapshot();state.entries.Add(old);AppLibrary.Merge(state,new[]{Found(desktop,newTarget,"")});Check(state.entries.Count==1&&state.entries[0].id=="upgrade-id"&&old.target==newTarget&&old.folder=="chosen-folder"&&old.order==4,"same shortcut upgraded in place keeps old ID and placement");
  AppLibrary.Merge(state,new[]{Found(desktop,newTarget,"")});Check(state.entries.Count==1&&state.entries[0].id=="upgrade-id","repeated scan is stable");
  old.identity=AppLibrary.Identity(oldTarget,"");old.target=oldTarget;state.entries.Add(newer);AppLibrary.Merge(state,new[]{Found(desktop,newTarget,"")});Check(state.entries.Count==1&&state.entries[0]==newer&&newer.folder=="chosen-folder"&&newer.order==4,"existing current-version entry retains its launch signature and inherits prior placement");
  var casing=Found(desktop,newTarget.ToUpperInvariant(),"");casing.id="case-id";state=new AppLibrarySnapshot();state.entries.Add(casing);AppLibrary.Merge(state,new[]{Found(desktop,newTarget,"")});Check(casing.target==newTarget.ToUpperInvariant(),"path casing alone cannot invalidate an existing sharing signature");
  var retained=Found(desktop,oldTarget,"");retained.id="old-app";retained.sources.Add(menu);state=new AppLibrarySnapshot();state.entries.Add(retained);AppLibrary.Merge(state,new[]{Found(desktop,newTarget,""),Found(menu,oldTarget,"")});Check(state.entries.Count==2&&retained.path==menu&&retained.target==oldTarget,"changing one source splits it while another source still refers to the old target");
  string game1=Path.Combine(fixture,"game1.url"),game2=Path.Combine(fixture,"game2.url"),otherGame=Path.Combine(fixture,"other-game.url");File.WriteAllText(game1,"[InternetShortcut]\r\nURL=steam://rungameid/2001120\r\n");File.Copy(game1,game2);File.WriteAllText(otherGame,"[InternetShortcut]\r\nURL=steam://rungameid/2860650\r\n");
  using(var library=new AppLibrary(Path.Combine(fixture,"games"))){library.Add(game1);library.Add(game2);library.Add(otherGame);Check(library.GetSnapshot().entries.Count(e=>e.kind!="action")==2,"URL aliases merge by destination while different games remain distinct");var entry=library.GetSnapshot().entries.Single(e=>e.path==game1);Check(entry.sources.Count==2&&entry.target==game1&&entry.arguments=="","URL merge keeps original launch file and signature");Reject(()=>library.Repair(library.GetSnapshot().entries.Single(e=>e.path==otherGame).id,game2),"repair rejects equivalent URL alias");}
  File.WriteAllText(otherGame,"[InternetShortcut]\r\nURL=https://example.test/A?profile=2\r\n");File.WriteAllText(game2,"[InternetShortcut]\r\nURL=https://example.test/a?profile=2\r\n");Check(AppLibrary.MatchIdentity(AppLibrary.Identity(otherGame,""))!=AppLibrary.MatchIdentity(AppLibrary.Identity(game2,"")),"case-sensitive URL paths are not collapsed");
  File.WriteAllText(game2,"invalid");Check(AppLibrary.MatchIdentity(AppLibrary.Identity(game2,""))==AppLibrary.Identity(game2,""),"invalid URL falls back to file identity");
  File.WriteAllText(game2,"[InternetShortcut]\r\nURL=https://example.test/updated\r\n");Check(AppLibrary.MatchIdentity(AppLibrary.Identity(game2,""))=="url:\nhttps://example.test/updated","rewritten URL uses current file content instead of the shell cache");
  File.WriteAllText(game2,"[Other]\r\nURL=https://example.test/wrong\r\n[InternetShortcut]\r\nURL=https://example.test/照片\r\n",System.Text.Encoding.Unicode);Check(AppLibrary.MatchIdentity(AppLibrary.Identity(game2,""))=="url:\nhttps://example.test/照片","Unicode shortcut reads only the InternetShortcut section");
 }
 [STAThread] static int Main(){
  string fixture=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app-library-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);
  try {
   string first=Path.Combine(fixture,"微信.txt"),second=Path.Combine(fixture,"另一文件.txt"),third=Path.Combine(fixture,"替换入口.txt");File.WriteAllText(first,"source unchanged");File.WriteAllText(second,"second");File.WriteAllText(third,"replacement");
   string map=Path.Combine(Environment.CurrentDirectory,"src","LiquidDesktop","app-center-pinyin.txt");if(File.Exists(map))File.Copy(map,Path.Combine(fixture,"app-center-pinyin.txt"));
   using(var library=new AppLibrary(fixture)){
    library.Add(first);library.Add(second);library.Add(first);var s=library.GetSnapshot();var entries=s.entries.Where(e=>e.kind!="action").ToList();Check(entries.Count==2,"manual add deduplicates by target");Check(entries.All(e=>e.exists),"adding does not invalidate prior entries");string a=entries.First(e=>e.path==first).id,b=entries.First(e=>e.path==second).id;
    Check(s.entries.Count(e=>e.kind=="action")==4,"system actions are explicit IDs");Check(entries.First(e=>e.id==a).search.Contains("weixin"),"offline Mandarin search index");Check(entries.First(e=>e.id==a).initials.StartsWith("wx"),"Mandarin initials");
    library.Apply("alias",b,"","网易云音乐 快乐");var music=library.GetSnapshot().entries.First(e=>e.id==b);Check(music.search.Contains("wangyiyunyinyue"),"music uses contextual yue pronunciation");Check(music.initials.Contains("wyyyy"),"music initials match the contextual pronunciation");Check(music.search.Contains("kuaile"),"other uses of le keep their original pronunciation");
    library.Apply("categoryCreate","","","我的分类");string category=library.GetSnapshot().categories.First(c=>c.name=="我的分类").id;library.Apply("move",a,category,"");library.Apply("move",b,category,"");library.Apply("group",a,b,"工具");s=library.GetSnapshot();string folder=s.folders.Single().id;Check(s.entries.First(e=>e.id==a).folder==folder&&s.entries.First(e=>e.id==b).folder==folder,"group commits two entries together");
    Reject(()=>library.Apply("move",folder,folder,""),"folder nesting rejected");library.Apply("folderRename",folder,"","常用工具");library.Apply("reorder",b,a,"");s=library.GetSnapshot();Check(s.entries.First(e=>e.id==b).order<s.entries.First(e=>e.id==a).order,"folder order persists");
    library.Apply("alias",a,"","we chat 聊天");using(var reloaded=new AppLibrary(fixture)){Check(reloaded.Find(a).folder==folder&&reloaded.Find(a).alias=="we chat 聊天","reload retains folder and alias");reloaded.Apply("categoryRename",category,"","重命名分类");Check(library.GetSnapshot().categories.Any(c=>c.name=="重命名分类"),"second process reads the replacement library without restarting");}library.Apply("alias",b,"","second");Check(library.GetSnapshot().categories.Any(c=>c.name=="重命名分类"),"mutation merges current disk state");
    library.Apply("folderDelete",folder,"","");s=library.GetSnapshot();Check(s.entries.Where(e=>e.id==a||e.id==b).All(e=>e.folder==""&&e.category==category),"folder deletion restores parent category");library.Apply("categoryDelete",category,"","");Check(library.Find(a).category=="uncategorized","category deletion keeps entries");Reject(()=>library.Apply("categoryDelete","uncategorized","",""),"uncategorized cannot be deleted");
    library.Repair(a,third);Check(library.Find(a).path==third,"repair preserves stable entry ID");Reject(()=>library.Repair(a,second),"repair cannot silently merge two targets");library.Apply("remove",b,"","");Check(library.Find(b)==null&&File.Exists(second),"remove only deletes library record");library.Add(second);Check(library.GetSnapshot().entries.Count(e=>e.path==second)==1,"explicit add restores excluded entry");Check(File.ReadAllText(first)=="source unchanged","source contents preserved");
    long revision=library.GetSnapshot().revision;Reject(()=>library.Apply("categoryCreate","","",new string('x',81)),"invalid name rejected");Check(library.GetSnapshot().revision==revision,"failed mutation not committed");
    var stale=library.GetSnapshot();string store=Path.Combine(fixture,"app-library.json"),external=File.ReadAllText(store)+" ";File.WriteAllText(store,external);
    var commit=typeof(AppLibrary).GetMethod("Commit",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);bool conflict=false;try{commit.Invoke(library,new object[]{stale});}catch(System.Reflection.TargetInvocationException ex){conflict=ex.InnerException is IOException;}
    Check(conflict&&File.ReadAllText(store)==external,"a change after reading cannot be overwritten by a stale commit");
    Check(!Directory.EnumerateFiles(fixture,"*.tmp").Any(),"conflict cleans its temporary write");
   }
   string shortcut=Path.Combine(fixture,"启动器.lnk"),args="--profile \"中文 profile\" --mode original";Shortcut(shortcut,first,args);
   using(var library=new AppLibrary(fixture)){library.Add(shortcut);var entry=library.GetSnapshot().entries.Single(e=>e.path==shortcut);Check(entry.identity==AppLibrary.Identity(first,args)&&entry.arguments==""&&entry.target==first,"shortcut entry keeps its launch arguments inside the original link instead of invoking the bare host");library.Repair(entry.id,shortcut);Check(library.Find(entry.id).path==shortcut&&library.Find(entry.id).identity==entry.identity,"repair keeps the shortcut and its argument-bearing identity");}
   var state=new AppLibrarySnapshot();state.categories.Add(new AppLibraryCategory{id="uncategorized",name="未分类"});string identity=AppLibrary.Identity(first,"");AppLibrary.Merge(state,new[]{new AppLibraryEntry{identity=identity,name="同名",path=first,exists=true,sources=new List<string>{first}},new AppLibraryEntry{identity=identity,name="同名",path=second,exists=true,sources=new List<string>{second}},new AppLibraryEntry{identity=AppLibrary.Identity(third,""),name="同名",path=third,exists=true,sources=new List<string>{third}}});Check(state.entries.Count==2&&state.entries[0].sources.Count==2,"same identity merges sources, same name different target retained");
   state.entries[0].category="games";state.entries[0].exists=false;AppLibrary.Merge(state,new[]{new AppLibraryEntry{identity=identity,name="新名称",path=first,exists=true,sources=new List<string>{first}}});Check(state.entries[0].category=="games"&&state.entries[0].exists,"rescan keeps manual category and stable ID");state.excluded.Add(identity);state.entries.RemoveAt(0);AppLibrary.Merge(state,new[]{new AppLibraryEntry{identity=identity,name="同名",path=first,sources=new List<string>{first}}});Check(state.entries.Count==1,"excluded identity does not return on scan");
   DedupChecks(fixture);
   string data=Path.Combine(fixture,"app-library.json");File.WriteAllText(data,"invalid JSON");using(var broken=new AppLibrary(fixture)){Check(broken.GetSnapshot().error.Contains("读取失败"),"corrupt file has actionable error");Reject(()=>broken.Add(first),"corrupt file not overwritten by mutation");Check(File.ReadAllText(data)=="invalid JSON","corrupt source retained");}
   Console.WriteLine("AppLibrary: "+checks+" behavior checks passed.");return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(fixture.StartsWith(AppDomain.CurrentDomain.BaseDirectory,StringComparison.OrdinalIgnoreCase)&&Directory.Exists(fixture))Directory.Delete(fixture,true);}
 }
}
